create function pg_temp.query_assert(ok boolean,label text)returns void language plpgsql as $$begin if ok is not true then raise exception 'ADMIN QUERY ASSERTION: %',label;end if;end$$;
create function pg_temp.query_error(statement text,expected text)returns void language plpgsql as $$begin begin execute statement;exception when others then if strpos(sqlerrm,expected)>0 or sqlstate=expected then return;end if;raise exception 'Unexpected error: % (expected %)',sqlerrm,expected;end;raise exception 'Missing error: %',expected;end$$;
create function pg_temp.query_as(actor uuid)returns void language plpgsql as $$begin perform set_config('request.jwt.claim.sub',coalesce(actor::text,''),true);perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role',case when actor is null then 'anon' else 'authenticated' end,'session_id',md5(actor::text||':query-session')::uuid)::text,true);end$$;
